                readback_data_var = hwif_in.aon[i0].WAKE_LOCK_READ.rd_data;
            end
            if(rd_mux_addr == 14'h302c + (14)'(i0) * 14'h100) begin
                readback_data_var = hwif_in.aon[i0].WAKE_ENABLE_READ.rd_data;
            end
            if(rd_mux_addr == 14'h3030 + (14)'(i0) * 14'h100) begin
                readback_data_var = hwif_in.aon[i0].WAKE_MODE_READ0.rd_data;
            end
            if(rd_mux_addr == 14'h3034 + (14)'(i0) * 14'h100) begin
                readback_data_var = hwif_in.aon[i0].WAKE_MODE_READ1.rd_data;
            end
            if(rd_mux_addr == 14'h3038 + (14)'(i0) * 14'h100) begin
                readback_data_var = hwif_in.aon[i0].WAKE_MODE_READ2.rd_data;
            end
            if(rd_mux_addr == 14'h303c + (14)'(i0) * 14'h100) begin
                readback_data_var = hwif_in.aon[i0].WAKE_DIV_READ.rd_data;
            end
            if(rd_mux_addr == 14'h3040 + (14)'(i0) * 14'h100) begin
                readback_data_var = hwif_in.aon[i0].WAKE_COUNT_READ.rd_data;
            end
        end
        readback_data = readback_data_var;
        readback_done = decoded_req & ~decoded_req_is_wr & ~decoded_req_is_external;
        readback_err = decoded_err;
    end

    assign external_rd_ack = readback_external_rd_ack;
    assign cpuif_rd_ack = readback_done | readback_external_rd_ack;
    assign cpuif_rd_data = readback_data;
    assign cpuif_rd_err = readback_err;
endmodule
